fn solve(r1: i8, c1: i8, r2: i8, c2: i8) -> Vec<i8> {
    // Work in i16 to avoid any edge-case overflow on abs() for signed integers.
    let r1i = r1 as i16;
    let c1i = c1 as i16;
    let r2i = r2 as i16;
    let c2i = c2 as i16;

    // Rook
    let rook_moves: i8 = if r1 == r2 && c1 == c2 {
        0
    } else if r1 == r2 || c1 == c2 {
        1
    } else {
        2
    };

    // Bishop
    let bishop_moves: i8 = if r1 == r2 && c1 == c2 {
        0
    } else {
        let same_color = ((r1i + c1i) & 1) == ((r2i + c2i) & 1);
        if !same_color {
            0
        } else {
            let dr = (r1i - r2i).abs();
            let dc = (c1i - c2i).abs();
            if dr == dc {
                1
            } else {
                2
            }
        }
    };

    // King (Chebyshev distance)
    let dr = (r1i - r2i).abs();
    let dc = (c1i - c2i).abs();
    let king_moves: i8 = dr.max(dc) as i8;

    vec![rook_moves, bishop_moves, king_moves]
}